import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.ClWLC0WE.js";const u=JSON.parse('{"title":"Data Types","description":"","frontmatter":{},"headers":[],"relativePath":"guide/data-types.md","filePath":"guide/data-types.md","lastUpdated":1776546025000}'),c={name:"guide/data-types.md"};function n(i,t,r,s,l,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data Types&quot;">​</a></h1><p>Delta-Pack schemas are built from a fixed set of data types, each with a defined snapshot encoding, diff encoding, and parsing rules. Every type is available across all language implementations.</p><p>Types fall into three groups — <strong>primitives</strong>, <strong>containers</strong>, and <strong>named types</strong> — described below.</p><h3 id="primitives" tabindex="-1">Primitives <a class="header-anchor" href="#primitives" aria-label="Permalink to &quot;Primitives&quot;">​</a></h3><p>Primitives represent the basic scalar values:</p><table tabindex="0"><thead><tr><th>Type</th><th>YAML Syntax</th><th>JSON Example</th><th>Encode</th><th>Diff</th></tr></thead><tbody><tr><td>String</td><td><code>string</code></td><td><code>&quot;hello&quot;</code></td><td>UTF-8 with per-message dictionary compression</td><td>New value (old value pre-loaded in dictionary)</td></tr><tr><td>Int</td><td><code>int</code></td><td><code>42</code>, <code>-7</code></td><td>ZigZag varint</td><td>New value</td></tr><tr><td>Int (bounded)</td><td><code>int(min=0, max=100)</code></td><td><code>50</code></td><td>Bit-packed in <code>log₂(max − min + 1)</code> bits</td><td>New value</td></tr><tr><td>Uint</td><td><code>uint</code></td><td><code>42</code></td><td>Varint (shorthand for <code>int(min=0)</code>)</td><td>New value</td></tr><tr><td>Float</td><td><code>float</code></td><td><code>3.14</code></td><td>IEEE 754 32-bit</td><td>New value</td></tr><tr><td>Float (quantized)</td><td><code>float(precision=0.01)</code></td><td><code>3.14</code></td><td><code>round(value / precision)</code> as ZigZag varint</td><td>New value</td></tr><tr><td>Boolean</td><td><code>boolean</code></td><td><code>true</code></td><td>Single bit (RLE-compressed)</td><td>Change bit (decoder flips old value)</td></tr></tbody></table><h3 id="containers" tabindex="-1">Containers <a class="header-anchor" href="#containers" aria-label="Permalink to &quot;Containers&quot;">​</a></h3><p>Containers wrap other types:</p><table tabindex="0"><thead><tr><th>Type</th><th>YAML Schema</th><th>JSON Example</th><th>Encode</th><th>Diff</th></tr></thead><tbody><tr><td>Array</td><td><code>int[]</code></td><td><code>[1, 2, 3]</code></td><td>Length prefix + elements in sequence</td><td>New length + sparse updates (index + element diff) + appended elements</td></tr><tr><td>Map</td><td><code>&lt;string, int&gt;</code></td><td><code>{&quot;a&quot;: 1, &quot;b&quot;: 2}</code></td><td>Length prefix + key-value pairs</td><td>Positional deletions + positional updates (with value diffs) + keyed additions</td></tr><tr><td>Optional</td><td><code>string?</code></td><td><code>&quot;value&quot;</code> or <code>null</code></td><td>Presence bit + value if present</td><td>Was null: new value directly; was non-null: presence bit + value diff</td></tr></tbody></table><h3 id="named-types" tabindex="-1">Named Types <a class="header-anchor" href="#named-types" aria-label="Permalink to &quot;Named Types&quot;">​</a></h3><p>Named types are the only types that can be directly encoded/decoded or used as the codegen <code>--type</code>:</p><table tabindex="0"><thead><tr><th>Type</th><th>YAML Schema</th><th>JSON Example</th><th>Encode</th><th>Diff</th></tr></thead><tbody><tr><td>Object</td><td><code>Position:</code><br>  <code>x: float</code><br>  <code>y: float</code></td><td><code>{&quot;x&quot;: 1.5, &quot;y&quot;: 2.0}</code></td><td>Fields in declaration order</td><td>Change bit + per-field change bits with diffs</td></tr><tr><td>Enum</td><td><code>Team:</code><br>  <code>- RED</code><br>  <code>- BLUE</code><br>  <code>- GREEN</code></td><td><code>&quot;RED&quot;</code></td><td><code>log₂(variant count)</code> bits</td><td>New value</td></tr><tr><td>Union</td><td><code>Contact:</code><br>  <code>- EmailContact</code><br>  <code>- PhoneContact</code></td><td><code>{&quot;EmailContact&quot;: {&quot;email&quot;: &quot;...&quot;}}</code></td><td>Variant bits + variant fields</td><td>Same type: per-field diffs; new type: variant bits + full encode</td></tr><tr><td>Type alias</td><td><code>UserId: string</code></td><td><code>&quot;abc123&quot;</code></td><td>Resolved to underlying type</td><td>Resolved to underlying type</td></tr></tbody></table><h3 id="language-bindings" tabindex="-1">Language bindings <a class="header-anchor" href="#language-bindings" aria-label="Permalink to &quot;Language bindings&quot;">​</a></h3><p>How each schema type is represented in TypeScript, C#, and Rust:</p><table tabindex="0"><thead><tr><th>Schema type</th><th>TypeScript</th><th>C#</th><th>Rust</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>string</code></td><td><code>string</code></td><td><code>String</code></td></tr><tr><td><code>int</code>, <code>int(min,max)</code></td><td><code>number</code></td><td><code>long</code></td><td><code>i64</code></td></tr><tr><td><code>uint</code></td><td><code>number</code></td><td><code>long</code></td><td><code>u64</code></td></tr><tr><td><code>float</code>, <code>float(p)</code></td><td><code>number</code></td><td><code>float</code></td><td><code>f32</code></td></tr><tr><td><code>boolean</code></td><td><code>boolean</code></td><td><code>bool</code></td><td><code>bool</code></td></tr><tr><td><code>T[]</code></td><td><code>T[]</code></td><td><code>List&lt;T&gt;</code></td><td><code>Vec&lt;T&gt;</code></td></tr><tr><td><code>T?</code></td><td><code>T | undefined</code></td><td><code>T?</code></td><td><code>Option&lt;T&gt;</code></td></tr><tr><td><code>&lt;K, V&gt;</code></td><td><code>Map&lt;K, V&gt;</code></td><td><code>OrderedDictionary&lt;K, V&gt;</code></td><td><code>IndexMap&lt;K, V&gt;</code></td></tr><tr><td>Object</td><td><code>type</code> (structural)</td><td><code>class</code></td><td><code>struct</code></td></tr><tr><td>Enum</td><td>string literal union</td><td><code>enum</code></td><td><code>enum</code></td></tr><tr><td>Union</td><td>discriminated union (<code>_type</code>)</td><td>abstract class + variant subclasses</td><td><code>enum</code> (tagged)</td></tr><tr><td>Type alias</td><td>resolved to underlying type</td><td>resolved to underlying type</td><td>resolved to underlying type</td></tr></tbody></table><h3 id="binary-layout" tabindex="-1">Binary layout <a class="header-anchor" href="#binary-layout" aria-label="Permalink to &quot;Binary layout&quot;">​</a></h3><p>Every encoded message shares the same structure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[data section][RLE bits][bit count (reverse varint)]</span></span></code></pre></div><p>The <strong>data section</strong> holds whole-byte values (strings, varints, floats). The <strong>RLE section</strong> holds packed bits (booleans, enums, bounded integers, and change flags). The bit count at the end lets the decoder find the boundary.</p><p>Diff compactness comes from <strong>change bits</strong>: inside objects, unions, arrays, and maps, each field or element is preceded by a single bit in the RLE section. If it&#39;s <code>0</code>, nothing else is encoded for that field — the decoder keeps the old value.</p>',20)])])}const b=d(c,[["render",n]]);export{u as __pageData,b as default};
